CREATE EXTENSION IF NOT EXISTS vector;


-- updated_at 자동 갱신 트리거
CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ LANGUAGE 'plpgsql';

-- 트리거 적용
CREATE TRIGGER update_users_updated_at 
    BEFORE UPDATE ON users
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

CREATE TRIGGER update_scenarios_updated_at 
    BEFORE UPDATE ON scenarios
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

CREATE TRIGGER update_game_sessions_updated_at 
    BEFORE UPDATE ON game_sessions
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

CREATE TRIGGER update_board_nodes_updated_at 
    BEFORE UPDATE ON board_nodes
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

CREATE TRIGGER update_reviews_updated_at 
    BEFORE UPDATE ON reviews
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();


-- 시나리오 통계 자동 갱신 트리거
CREATE OR REPLACE FUNCTION update_scenario_stats()
RETURNS TRIGGER AS $$
BEGIN
    UPDATE scenarios SET
        avg_rating = (
            SELECT AVG(rating) FROM reviews 
            WHERE scenario_id = COALESCE(NEW.scenario_id, OLD.scenario_id) 
            AND is_deleted = FALSE
        ),
        avg_difficulty = (
            SELECT AVG(difficulty) FROM reviews 
            WHERE scenario_id = COALESCE(NEW.scenario_id, OLD.scenario_id) 
            AND is_deleted = FALSE
        )
    WHERE id = COALESCE(NEW.scenario_id, OLD.scenario_id);
    RETURN NEW;
END;
$$ LANGUAGE 'plpgsql';

CREATE TRIGGER update_scenario_stats_trigger 
    AFTER INSERT OR UPDATE OR DELETE ON reviews
    FOR EACH ROW EXECUTE FUNCTION update_scenario_stats();


-- 게임 세션 만료일 자동 설정 트리거
CREATE OR REPLACE FUNCTION set_session_expires_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.expires_at = NEW.created_at + INTERVAL '7 days';
    RETURN NEW;
END;
$$ LANGUAGE 'plpgsql';

CREATE TRIGGER set_game_session_expires_at
    BEFORE INSERT ON game_sessions
    FOR EACH ROW EXECUTE FUNCTION set_session_expires_at();

--  범행 동기 유사도 계산 함수
CREATE OR REPLACE FUNCTION calculate_motive_similarity(
    p_session_id BIGINT
) RETURNS FLOAT AS $$
DECLARE
    v_similarity FLOAT;
BEGIN
    SELECT 1 - (gs.submitted_motive_embedding <=> s.correct_motive_embedding)
    INTO v_similarity
    FROM game_sessions gs
    JOIN scenarios s ON s.id = gs.scenario_id
    WHERE gs.id = p_session_id
    AND gs.submitted_motive_embedding IS NOT NULL
    AND s.correct_motive_embedding IS NOT NULL;

    RETURN COALESCE(v_similarity, 0);
END;
$$ LANGUAGE 'plpgsql';


-- 사인 유사도 계산 함수
CREATE OR REPLACE FUNCTION calculate_cause_similarity(
    p_session_id BIGINT
) RETURNS FLOAT AS $$
DECLARE
    v_similarity FLOAT;
BEGIN
    SELECT 1 - (gs.submitted_cause_of_death_embedding <=> s.correct_cause_of_death_embedding)
    INTO v_similarity
    FROM game_sessions gs
    JOIN scenarios s ON s.id = gs.scenario_id
    WHERE gs.id = p_session_id
    AND gs.submitted_cause_of_death_embedding IS NOT NULL
    AND s.correct_cause_of_death_embedding IS NOT NULL;

    RETURN COALESCE(v_similarity, 0);
END;
$$ LANGUAGE 'plpgsql';


